CREATE TABLE milestone_records(id INTEGER PRIMARY KEY, category TEXT NOT NULL CHECK(category IN ('topic','midterm')), student_number TEXT NOT NULL, assessment_batch TEXT NOT NULL, student_id INTEGER REFERENCES students(id), payload TEXT NOT NULL, source_row_id INTEGER NOT NULL UNIQUE REFERENCES import_rows(id), version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, UNIQUE(student_number,category,assessment_batch));